def induction_score(A, ids, qrange):
    T=len(ids); last={}; prev_next=np.full(T,-1)
    for j in range(T):
        if ids[j] in last: prev_next[j]=last[ids[j]]+1
        last[ids[j]]=j
    sc=np.zeros(A.shape[0]); n=0
    for q in qrange:
        if prev_next[q]>=0 and prev_next[q]<=q:
            sc+=A[:,q,prev_next[q]]; n+=1
    return sc/max(n,1)
